  2384  prepareDecodeNodeIdJson(UA_NodeId *dst, CtxJson *ctx, ParseCtx *parseCtx,
  2385                          u8 *fieldCount, DecodeEntry *entries) {
  2386      /* possible keys: Id, IdType*/
  2387      /* Id must always be present */
  2388      entries[*fieldCount].fieldName = UA_JSONKEY_ID;
  2389      entries[*fieldCount].found = false;
  2390      entries[*fieldCount].type = NULL;
  2391
  2392      /* IdType */
  2393      UA_Boolean hasIdType = false;
  2394      size_t searchResult = 0;
  2395      status ret = lookAheadForKey(UA_JSONKEY_IDTYPE, ctx, parseCtx, &searchResult);
  2396      if(ret == UA_STATUSCODE_GOOD) { /*found*/
  2397           hasIdType = true;
  2398      }
  2399
  2400      if(hasIdType) {
  2401          size_t size = (size_t)(parseCtx->tokenArray[searchResult].end -
  2402                                 parseCtx->tokenArray[searchResult].start);
  2403          if(size < 1) {
  2404              return UA_STATUSCODE_BADDECODINGERROR;
  2405          }
  2406
  2407          char *idType = (char*)(ctx->pos + parseCtx->tokenArray[searchResult].start);
  2408
  2409          if(idType[0] == '2') {
  2410              dst->identifierType = UA_NODEIDTYPE_GUID;
  2411              entries[*fieldCount].fieldPointer = &dst->identifier.guid;
  2412              entries[*fieldCount].function = (decodeJsonSignature) Guid_decodeJson;
  2413          } else if(idType[0] == '1') {
  2414              dst->identifierType = UA_NODEIDTYPE_STRING;
  2415              entries[*fieldCount].fieldPointer = &dst->identifier.string;
  2416              entries[*fieldCount].function = (decodeJsonSignature) String_decodeJson;
  2417          } else if(idType[0] == '3') {
  2418              dst->identifierType = UA_NODEIDTYPE_BYTESTRING;
  2419              entries[*fieldCount].fieldPointer = &dst->identifier.byteString;
  2420              entries[*fieldCount].function = (decodeJsonSignature) ByteString_decodeJson;
  2421          } else {
  2422              return UA_STATUSCODE_BADDECODINGERROR;
  2423          }
  2424
  2425          /* Id always present */
  2426          (*fieldCount)++;
  2427
  2428          entries[*fieldCount].fieldName = UA_JSONKEY_IDTYPE;
  2429          entries[*fieldCount].fieldPointer = NULL;
  2430          entries[*fieldCount].function = NULL;
  2431          entries[*fieldCount].found = false;
  2432          entries[*fieldCount].type = NULL;
  2433
  2434          /* IdType */
  2435          (*fieldCount)++;
  2436      } else {
  2437          dst->identifierType = UA_NODEIDTYPE_NUMERIC;
  2438          entries[*fieldCount].fieldPointer = &dst->identifier.numeric;
  2439          entries[*fieldCount].function = (decodeJsonSignature) UInt32_decodeJson;
  2440          entries[*fieldCount].type = NULL;
  2441          (*fieldCount)++;
  2442      }
  2443
  2444      return UA_STATUSCODE_GOOD;
  2445  }
