  2790          parseCtx->index = (UA_UInt16)searchTypeIdResult;
  2791          ret = NodeId_decodeJson(&typeId, &UA_TYPES[UA_TYPES_NODEID], ctx, parseCtx, true);
  2792          if(ret != UA_STATUSCODE_GOOD)
  2793              return ret;
  2794
  2795          /*restore*/
  2796          parseCtx->index = index;
  2797          const UA_DataType *typeOfBody = UA_findDataType(&typeId);
  2798          if(!typeOfBody) {
  2799              /*dont decode body: 1. save as bytestring, 2. jump over*/
  2800              dst->encoding = UA_EXTENSIONOBJECT_ENCODED_BYTESTRING;
  2801              UA_NodeId_copy(&typeId, &dst->content.encoded.typeId);
  2802
  2803              /*Check if Object in Extentionobject*/
  2804              if(getJsmnType(parseCtx) != JSMN_OBJECT) {
  2805                  UA_NodeId_deleteMembers(&typeId);
  2806                  return UA_STATUSCODE_BADDECODINGERROR;
  2807              }
  2808
  2809              /*Search for Body to save*/
  2810              size_t searchBodyResult = 0;
  2811              ret = lookAheadForKey(UA_JSONKEY_BODY, ctx, parseCtx, &searchBodyResult);
  2812              if(ret != UA_STATUSCODE_GOOD) {
  2813                  /*No Body*/
  2814                  UA_NodeId_deleteMembers(&typeId);
  2815                  return UA_STATUSCODE_BADDECODINGERROR;
  2816              }
  2817
  2818              if(searchBodyResult >= (size_t)parseCtx->tokenCount) {
  2819                  /*index not in Tokenarray*/
  2820                  UA_NodeId_deleteMembers(&typeId);
  2821                  return UA_STATUSCODE_BADDECODINGERROR;
  2822              }
  2823
  2824              /* Get the size of the Object as a string, not the Object key count! */
  2825              UA_Int64 sizeOfJsonString =(parseCtx->tokenArray[searchBodyResult].end -
  2826                      parseCtx->tokenArray[searchBodyResult].start);
  2827
  2828              char* bodyJsonString = (char*)(ctx->pos + parseCtx->tokenArray[searchBodyResult].start);
  2829
  2830              if(sizeOfJsonString <= 0) {
  2831                  UA_NodeId_deleteMembers(&typeId);
  2832                  return UA_STATUSCODE_BADDECODINGERROR;
  2833              }
  2834
  2835              /* Save encoded as bytestring. */
  2836              ret = UA_ByteString_allocBuffer(&dst->content.encoded.body, (size_t)sizeOfJsonString);
  2837              if(ret != UA_STATUSCODE_GOOD) {
  2838                  UA_NodeId_deleteMembers(&typeId);
  2839                  return ret;
  2840              }
  2841
  2842              memcpy(dst->content.encoded.body.data, bodyJsonString, (size_t)sizeOfJsonString);
  2843
  2844              size_t tokenAfteExtensionObject = 0;
  2845              jumpOverObject(ctx, parseCtx, &tokenAfteExtensionObject);
  2846
  2847              if(tokenAfteExtensionObject == 0) {
  2848                  /*next object token not found*/
  2849                  UA_NodeId_deleteMembers(&typeId);
  2850                  UA_ByteString_deleteMembers(&dst->content.encoded.body);
  2851                  return UA_STATUSCODE_BADDECODINGERROR;
  2852              }
  2853
  2854              parseCtx->index = (UA_UInt16)tokenAfteExtensionObject;
  2855
  2856              return UA_STATUSCODE_GOOD;
  2857          }
